create schema if not exists control_center;
create table if not exists control_center.omni_outbox (id text primary key default ('OUT-' || upper(substr(md5(random()::text),1,12))), channel text not null, conv_id text, msg_ts bigint, to_addr text not null, kind text not null default 'text', body jsonb not null default '{}', status text not null default 'queued', provider_id text, error text, attempts int not null default 0, created_by text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists control_center.omni_events (id bigserial primary key, channel text, kind text, payload jsonb, ok boolean not null default true, error text, received_at timestamptz not null default now());
create table if not exists control_center._vault_stub (name text primary key, secret text, updated_at timestamptz default now());
create or replace function control_center.sg_omni_set_secret(p_name text, p_value text) returns void language plpgsql as $$ begin if coalesce(p_value,'')='' then delete from control_center._vault_stub where name='omni_'||p_name; else insert into control_center._vault_stub values ('omni_'||p_name, p_value, now()) on conflict (name) do update set secret=excluded.secret, updated_at=now(); end if; end $$;
create or replace function control_center.sg_omni_secret_status() returns table(name text, is_set boolean, updated_at timestamptz) language sql as $$ select substr(name,6), true, updated_at from control_center._vault_stub $$;
